// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

// Set は同じ値を 1 つしか持たない
const unique = new Set(a);
console.log(unique.size < a.length ? "Yes" : "No");
